(* LPS 727298f3: [rz_openat_toolong]'s 4096-byte name read is bounded by [TASK_SIZE]; with
   [4096 <= length path] it follows from the launch's bound on the path string (MainOpen's
   [path_facts]). *)
Lemma task_of_fit : forall (R : bvmap 5 word) (p : word) (n : nat),
  getr R 11 = p -> (4096 <= n)%nat -> bv_unsigned p + Z.of_nat n + 8 <= 0x800000000000 ->
  bv_unsigned (getr R 11) + 4096 <= TASK_SIZE.
Proof. intros R p n E Hn Hb. rewrite E. unfold TASK_SIZE. lia. Qed.

