  Context {fx : OSSVerify.Proofs.boost_json.fuzz_parse.lib.PropExec.FPState}.   (* [comment removed for export] *)
  Theorem main_realizes : ltac2:(zQ "10!po8@4$0?2fx?5HCEIL?2HS?2HM").
  (* LPS 727298f3 port: written out (the recorded proof destructed the old fifteen-field
     ProcInput).  The input is canonicalised to [mkProcInputC] over [amb_of inp]: every model
     term reads the input through its projections, and [mkProcInputC]'s image is [in_fs inp]
     with an empty /tmp, so [in_fs] of it is [in_fs inp] ([fs_seed_tmp] of [[]] computes to
     its argument); [main_entry] is a record, so it is rebuilt field by field.  The case split
     on the arguments is boost-beast/http_request's lib/MainTop.v [main_realizes]; the
     section theorems are applied with [eapply] and closed from the context, the entry
     fact first. *)
  Proof.
    intros sp0 tid brk mbase rnd lim inp regs mem ps0 B Hsp Hfit Hva Hve Hfs Htid HCE ME Hvl Hlau Hrdr
           RH0 KR0 AUX0 [HB HB64] TR FRM.
    set (AMB := amb_of inp).
    set (canon := @mkProcInputC AMB (in_argv inp) (in_envp inp) (in_fs inp) (in_stdin inp)).
    assert (ME' : @main_entry AMB canon mbase (Z_to_bv 64 290456) sp0 rnd tid regs mem)
      by (destruct ME; constructor; assumption).
    assert (Hvl' : valid_launch canon) by exact Hvl.
    assert (Hlau' : entry_launch_ok_va Sv48 (mkEntry sp0 brk mbase rnd) canon) by exact Hlau.
    assert (Hrdr' : in_channel_reader canon = true) by exact Hrdr.
    change (model0 tid brk mbase sp0 lim inp) with (model0 tid brk mbase sp0 lim canon) in KR0 |- *.
    clear ME Hvl Hlau Hrdr. subst canon.
    set (argv := in_argv inp) in *. set (envp := in_envp inp) in *.
    set (fs0 := in_fs inp) in *. set (stdin0 := in_stdin inp) in *.
    clearbody AMB argv envp fs0 stdin0. clear inp.
    destruct argv as [|a0s [|path [|x l]]].
    - apply (ref_usage sp0 [] envp rnd tid regs mem brk mbase lim fs0 stdin0 Hva Hve Hsp Htid ME' Hvl' Hlau' Hrdr' ltac:(cbn; lia) Hfit).
    - apply (ref_usage sp0 [a0s] envp rnd tid regs mem brk mbase lim fs0 stdin0 Hva Hve Hsp Htid ME' Hvl' Hlau' Hrdr' ltac:(cbn; lia) Hfit).
    - cbn [spec].
      pose proof Hva as (_ & _ & _ & _ & Htl). cbn [tl] in Htl. inversion Htl as [|x l [Hsl Hdd] _]; subst.
      destruct (Nat.leb_spec0 4096 (length path)) as [Hlong|Hshort].
      + eapply ref_open_fail_toolong; try exact ME'; try eassumption; try lia.
      + destruct (list_byte_eqb path []) eqn:Hemp.
        * apply list_byte_eqb_eq in Hemp.
          eapply ref_open_fail_empty; try exact ME'; try eassumption; try lia.
        * assert (Hne : path <> []) by (intros E; apply list_byte_eqb_eq in E; rewrite E in Hemp; discriminate).
          destruct (list_byte_eqb path dot_path) eqn:Hdot.
          -- apply list_byte_eqb_eq in Hdot.
             eapply ref_dir; try exact ME'; try eassumption; try lia.
          -- assert (Hnd : path <> dot_path) by (intros E; apply list_byte_eqb_eq in E; rewrite E in Hdot; discriminate).
             assert (Hdr : path_is_dirref path = false).
             { unfold path_is_dirref. rewrite (path_eqb_neq _ _ Hnd), Hdd. reflexivity. }
             destruct (fs_lookup fs0 path) as [data|] eqn:Hlk.
             ++ eapply ref_file; try exact ME'; try eassumption; try lia.
             ++ eapply ref_open_fail_absent; try exact ME'; try eassumption; try lia.
    - apply (ref_usage sp0 (a0s :: path :: x :: l) envp rnd tid regs mem brk mbase lim fs0 stdin0 Hva Hve Hsp Htid ME' Hvl' Hlau' Hrdr' ltac:(cbn; lia) Hfit).
  Qed.
End Top.
